beginning.embedded_functions:
#include <stdlib.h>
#include <mmt_core.h>
#include <tcpip/mmt_tcpip.h>

static inline bool em_print( const void * data, ...){
	return true;
}

static inline bool em_is_strong_version( uint16_t version ){
	return (version == DTLS_VERSION_1_2 ) || (version == DTLS_VERSION_1_3 );
}

static size_t    allow_ciphers_size = 0;
static uint16_t *allow_ciphers_list = NULL;

void on_load(){
	const char *str = getenv("MMT_SEC_DTLS_CIPHER_ALLOWLIST");
	if( str == NULL || str[0] == '\0' ){
		mmt_info("Rule 79.dtls_v12_ciphersuites: no value of MMT_SEC_DTLS_CIPHER_ALLOWLIST: ciphersuites are not checked" );
		return;
	}
	char **str_ciphers = NULL;
	allow_ciphers_size = str_split( str, ',', &str_ciphers );
	if( allow_ciphers_size == 0 )
		return;

	allow_ciphers_list = mmt_mem_alloc( sizeof( uint16_t ) * allow_ciphers_size );
	size_t i;
	for( i=0; i<allow_ciphers_size; i++ )
		allow_ciphers_list[i] = strtol( str_ciphers[i], NULL, 0 );

	mmt_mem_force_free( str_ciphers );

	//print info
	mmt_info("Rule 79.dtls_v12_ciphersuites: allow %zu ciphers", allow_ciphers_size );
	for( i=0; i<allow_ciphers_size; i++ )
		mmt_info("Rule 79.dtls_v12_ciphersuites: %zu: %hu", i, allow_ciphers_list[i] );
}

void on_unload(){
	if( allow_ciphers_list )
		mmt_mem_force_free( allow_ciphers_list );
}

//signalling cipher suite values that are not cipher suites
static inline bool _is_signalling_cipher_value( uint16_t cipher ){
	//TLS_EMPTY_RENEGOTIATION_INFO_SCSV (RFC 5746), TLS_FALLBACK_SCSV (RFC 7507)
	if( cipher == 0x00ff || cipher == 0x5600 )
		return true;
	//GREASE (RFC 8701): 0x0a0a, 0x1a1a, ..., 0xfafa
	return (cipher & 0x0f0f) == 0x0a0a && (cipher >> 8) == (cipher & 0xff);
}

static inline bool em_is_strong_ciphers( const mmt_u16_array_t *ciphers ){
	size_t i, j;
	//no allowlist: ciphersuites are not checked
	if( allow_ciphers_size == 0 )
		return true;
	for( i=0; i<ciphers->len; i++ ){
		if( _is_signalling_cipher_value( ciphers->data[i] ) )
			continue;
		for( j=0; j<allow_ciphers_size; j++ )
			if( allow_ciphers_list[j] == ciphers->data[i] )
				break;

		//when we visited all allow_ciphers_list but not found
		if( j >= allow_ciphers_size )
			return false;
	}
	return true;
}

/**
 * record   : dtls.p_data, the DTLS record starting by its 13-byte header
 * ciphers  : dtls.client_hello_cipher_suite
 */
static inline bool em_dtls_is_strong_client_hello( const void *record, const void *ciphers ){
	//record header (13) + handshake header (12) + client_version (2)
	const size_t min_len = 13 + 12 + 2;
	const uint8_t *p = (const uint8_t *) record;
	if( p == NULL || ciphers == NULL || mmt_mem_size( p ) < min_len )
		return true; //cannot check
	//a handshake record holding a ClientHello
	if( p[0] != 22 || p[13] != 1 )
		return true;
	//fragment_offset: only the first fragment holds client_version and the cipher suites
	if( p[19] != 0 || p[20] != 0 || p[21] != 0 )
		return true;
	uint16_t client_version = ((uint16_t) p[25] << 8) | p[26];
	return em_is_strong_version( client_version )
			&& em_is_strong_ciphers( (const mmt_u16_array_t *) ciphers );
}
